import{_ as t,o,c as a,ag as r}from"./chunks/framework.Bo7atV7P.js";const h=JSON.parse('{"title":"Monorepo Boundaries","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/repo-boundaries.md","filePath":"architecture/repo-boundaries.md","lastUpdated":1785933090000}'),i={name:"architecture/repo-boundaries.md"};function s(c,e,d,n,l,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="monorepo-boundaries" tabindex="-1">Monorepo Boundaries <a class="header-anchor" href="#monorepo-boundaries" aria-label="Permalink to &quot;Monorepo Boundaries&quot;">​</a></h1><h2 id="package-boundaries-inside-webentor-stack" tabindex="-1">Package boundaries inside <code>webentor-stack</code> <a class="header-anchor" href="#package-boundaries-inside-webentor-stack" aria-label="Permalink to &quot;Package boundaries inside `webentor-stack`&quot;">​</a></h2><ul><li><code>packages/webentor-core</code>: reusable PHP + JS runtime package.</li><li><code>packages/webentor-configs</code>: shared lint/format presets.</li><li><code>packages/webentor-setup</code>: shared setup runtime + CLI contract.</li><li><code>packages/webentor-starter</code>: starter template composition.</li><li><code>docs</code>: stack documentation (VitePress).</li></ul><h2 id="external-integration-target" tabindex="-1">External integration target <a class="header-anchor" href="#external-integration-target" aria-label="Permalink to &quot;External integration target&quot;">​</a></h2><ul><li><code>webentor-demo</code>: canonical integration project used as rollout gate.</li></ul><h2 id="ownership-model" tabindex="-1">Ownership model <a class="header-anchor" href="#ownership-model" aria-label="Permalink to &quot;Ownership model&quot;">​</a></h2><p>Shared/package-owned:</p><ul><li>reusable runtime behavior</li><li>setup runtime contract and upgrade recipes</li><li>shared lint/format rules</li><li>starter baseline composition</li></ul><p>Project-owned in consumer repos:</p><ul><li><code>scripts/.env.setup</code></li><li><code>scripts/hooks/*</code></li><li><code>scripts/project-specific/*</code></li><li>business/domain code</li></ul><h2 id="setup-metadata-contract" tabindex="-1">Setup metadata contract <a class="header-anchor" href="#setup-metadata-contract" aria-label="Permalink to &quot;Setup metadata contract&quot;">​</a></h2><p>Projects keep setup metadata in <code>.webikon/project.json</code> (schema v2). It declares four required fields — <code>schema_version</code>, <code>slug</code>, <code>stack</code>, <code>theme_path</code> — plus the optional <code>setup_cli_version</code>, written only where the project has a <code>scripts/setup-core/</code> subtree.</p><p>Current usage:</p><ul><li>created by <code>webentor-setup init</code>, which preserves a hand-set <code>stack</code> on re-runs</li><li>validated by <code>webentor-setup doctor</code>, which also fails on <code>setup_cli_version</code> drift</li><li>read by external tooling that needs the project&#39;s declared identity</li></ul><p>Current non-usage:</p><ul><li>setup shell runtime does not read this file directly during <code>scripts/setup.sh</code></li><li>it caches no feature toggles, and no version other than <code>setup_cli_version</code> — everything else is read from the artifact that owns it (theme Composer/pnpm lockfiles, root <code>composer.json</code>, <code>scripts/.env.setup</code>). Note <code>scripts/</code> is deploy-excluded, so the <code>SETUP_*</code> toggles are a checkout-only fact and the maintenance reporter does not carry them at all.</li></ul><p><code>setup_cli_version</code> is the one boundary the file deliberately crosses. Its artifact, <code>scripts/setup-core/composer.json</code>, sits behind the same deploy exclusion as the toggles — but unlike the toggles, something <em>does</em> act on it, so the value has to reach a deployed site somehow, and the declaration is that route. The inclusion rule reads accordingly: a fact must not be derivable <strong>from a deployed site</strong>, which is stricter than &quot;not derivable in the repo&quot;. <code>init</code> mirrors the artifact and never substitutes the running CLI&#39;s own version, so a project without setup-core has no such field. Because the value is declared, it can drift — a <code>git subtree pull</code> moves the artifact alone — so <code>doctor</code> exits 1 on mismatch and <code>webikon:update-webentor-packages-in-project</code> blocks. Fix the declaration to match the artifact, never the reverse.</p><p>Treat this file as declared project identity and keep it committed. The retired v1 file (<code>.webentor/project.json</code>) is deleted by <code>init</code>.</p>',18)])])}const m=t(i,[["render",s]]);export{h as __pageData,m as default};
